def transform(data):
    factors = {'B': 1, 'KiB': 1000, 'MiB': 1048576}
    return str(data['value'] * factors[data['unit']])

def transform(data):
    values = [s.strip() for s in data if s.strip()]
    return '\n'.join(sorted(set(values)))

def transform(data):
    totals = {}
    for item in data:
        group = item['group']
        totals[group] = totals.get(group, 0) + item['value']
    return '\n'.join(group + ':' + str(totals[group]) for group in sorted(totals))
